using MerciTantine.CardCatalog;
using MerciTantine.GameCore;
using MerciTantine.GameEngine;
using MerciTantine.Persistence;
using MerciTantine.AIPlayers;

var catalog=Catalog.Load(Path.Combine(AppContext.BaseDirectory,"Data"));
int passed=0,failed=0;
void Check(bool value,string message="Assertion échouée") { if(!value) throw new Exception(message); }
void Reject(Action action) { try { action(); } catch(RuleException) { return; } throw new Exception("Action illégale acceptée."); }
Engine New(int n=2) => Engine.New(catalog,Enumerable.Range(0,n).Select(i=>new PlayerSetup($"J{i}",i==0)),1234);
int Take(Engine e,string model,List<int> zone)
{
    int id=e.State.Rooms.SelectMany(r=>r.Objects.Concat(r.Secondary)).First(i=>e.Def(i).Id==model);
    foreach(var r in e.State.Rooms) { r.Objects.Remove(id); r.Secondary.Remove(id); }
    zone.Add(id);return id;
}
Engine Actions() { var e=New();e.State.Phase=Phase.Actions;return e; }
void Test(string name,Action run) { try { run();passed++;Console.WriteLine($"OK {name}"); } catch(Exception ex) { failed++;Console.WriteLine($"ÉCHEC {name} : {ex}"); } }
Test("200 cartes, 82 modèles, 60 emplacements",()=>{Check(catalog.CreateInstances().Count==200);Check(catalog.Cards.Count==82);Check(catalog.Distribution.Count(d=>d.Room!=null)==60);Check(catalog.Cards.Count(d=>d.Category==Category.Paper)==16);Check(catalog.Cards.Count(d=>d.Category==Category.Ally)==8);});
Test("Valeurs exceptionnelles et négatives",()=>{Check(catalog["lingot"].Value==25);Check(catalog["radioactif"].Value==-25);Check(catalog["pensions"].Value==-12);Check(catalog["rembrandt"].Value==20);});
Test("Deux catégories et suffisamment de cartes dans chaque pièce",()=>{var e=New(6);foreach(var r in e.State.Rooms){Check(r.Objects.Count+r.Secondary.Count>=20);Check(r.Objects.All(i=>e.Def(i).Category==Category.Object));Check(r.Secondary.All(i=>e.Def(i).Category==catalog.Rooms.Single(d=>d.Id==r.Id).Secondary));}e.AssertConservation();});
Test("Configuration humaine obligatoire",()=>Reject(()=>Engine.New(catalog,[new("A",false),new("B",false)],1)));
Test("Graine déterministe",()=>Check(SaveStore.Serialize(New())==SaveStore.Serialize(New())));
Test("Répartition surprise : chaque famille mélangée, effectifs équilibrés, aucune carte dupliquée",()=>{
    Check(catalog.Rules.RandomRoomDecks);
    for(ulong seed=1;seed<=12;seed++){
        var e=Engine.New(catalog,[new("A"),new("B")],seed);e.AssertConservation();Check(e.State.Cards.Count==200);
        foreach(var category in Enum.GetValues<Category>()){
            var rooms=e.State.Rooms.Where(r=>category==Category.Object||catalog.Rooms.Single(d=>d.Id==r.Id).Secondary==category).ToArray();
            var counts=rooms.Select(r=>category==Category.Object?r.Objects.Count:r.Secondary.Count).ToArray();Check(counts.Max()-counts.Min()<=1);
            foreach(var r in rooms)foreach(int id in category==Category.Object?r.Objects:r.Secondary){Check(e.Def(id).Category==category);Check(e.State.Cards[id].Origin==r.Id);}
        }
        var view=Views.For(e,0);Check(view.Rooms.All(r=>r.Risk==""));Check(view.Rooms.Select(r=>r.ExpectedValue).Distinct().Count()==1,"Avantage de pièce divulgué à l’IA");
        Check(SaveStore.Serialize(e)==SaveStore.Serialize(SaveStore.Deserialize(SaveStore.Serialize(e))));
    }
});
Test("Répartition surprise : les mêmes exemplaires changent de pièce selon la graine",()=>{
    var origins=Enumerable.Range(1,24).Select(seed=>Engine.New(catalog,[new("A"),new("B")],(ulong)seed).State.Cards).ToArray();
    foreach(string model in new[]{"suisse1","suisse2","suisse3","cambrioleur","lingot"}){
        int id=origins[0].First(c=>c.Model==model).Id;
        Check(origins.Select(cards=>cards[id].Origin).Distinct().Count()>1,$"Emplacement fixe : {model}");
    }
});
Test("Anciennes règles : répartition historique et sauvegarde préservées",()=>{
    var legacy=Catalog.Load(Path.Combine(AppContext.BaseDirectory,"Data"));legacy.Rules.RandomRoomDecks=false;
    var e=Engine.New(legacy,[new("A"),new("B")],42);Check(e.State.Cards.SequenceEqual(legacy.CreateInstances()));
    var copy=SaveStore.Deserialize(SaveStore.Serialize(e));Check(!copy.Catalog.Rules.RandomRoomDecks);Check(e.State.Cards.SequenceEqual(copy.State.Cards));
});
