Test("100 parties IA de 2 à 6 joueurs avec conservation",()=>{for(int g=0;g<100;g++){var e=Engine.New(catalog,Enumerable.Range(0,2+g%5).Select(i=>new PlayerSetup($"IA{i}",false,(Difficulty)((g+i)%3))),(ulong)g+1,true);int steps=0;while(e.State.Phase!=Phase.Finished){Check(++steps<2000,"Blocage IA");int seat=e.State.Phase==Phase.Reaction?e.State.Pending!.Target:e.State.Current;var v=Views.For(e,seat);var ai=new Agent(catalog.Rules);switch(e.State.Phase){case Phase.Explore:var x=ai.Explore(v);if(x.Room=="")e.SkipImpossibleExploration();else e.Explore(x.Room,x.First,x.Second);break;case Phase.Reaction:e.React(ai.React(v));break;case Phase.BurglaryChoice:e.ChooseBurglary(ai.ChooseBurglary(v));break;default:var action=ai.Decide(v);if(action==null)e.EndTurn();else Apply(e,action);break;}e.AssertConservation();}Check(e.Scores().Count==e.State.Players.Count);}});
