// Exercise every hostile model against each counter, including the notary's restrictions.
(Engine engine,int attack,int counter,int item) CounterFixture(string attackModel,string counterModel,Phase phase=Phase.Actions)
{
    var e=Actions();e.State.Phase=phase;e.Active.Cash=100;var victim=e.State.Players[1];victim.Cash=100;
    Take(e,"lingot",victim.Hidden);Take(e,"vase",e.Active.Hidden);Take(e,"abattement",victim.Hand);
    var def=e.Catalog[attackModel];int item=Take(e,def.TargetModel==""?"collier":def.TargetModel,victim.Declared);
