foreach(var attackDef in catalog.Cards.Where(d=>d.Hostile&&!d.Reaction))
foreach(string counterModel in new[]{"assurance","homme","chien","avocat"})
foreach(var phase in attackDef.Effect=="claim"&&attackDef.Category==Category.Paper?new[]{Phase.Actions,Phase.Notary}:new[]{Phase.Actions})
{
    var attackModel=attackDef.Id;var counter=counterModel;var stage=phase;
    Test($"Contre {counter} / {attackModel} / {stage}",()=>{
        var(e,attackId,counterId,item)=CounterFixture(attackModel,counter,stage);var victim=e.State.Players[1];
        bool legal=counter switch {"assurance"=>attackDef.Category==Category.Paper,"homme"=>true,"chien"=>new[]{"chapardeur","cambrioleur","pickpocket"}.Contains(attackModel),"avocat"=>attackDef.Effect=="claim"&&stage==Phase.Actions,_=>false};
        Check(e.ReactionCards().Contains(counterId)==legal,"Éligibilité du contre incorrecte.");
        if(!legal){string snapshot=SaveStore.Serialize(e);Reject(()=>e.React(counterId));Check(snapshot==SaveStore.Serialize(e),"Contre invalide non atomique.");e.AssertConservation();return;}
        Check(e.State.Phase==Phase.Reaction&&e.State.Pending?.Target==1);var hidden=victim.Hidden.ToArray();var declared=victim.Declared.ToArray();var hand=victim.Hand.Where(id=>id!=counterId).ToArray();int tax=victim.Tax,skip=victim.Skip;ulong random=e.State.RandomState;
        e=SaveStore.Deserialize(SaveStore.Serialize(e));victim=e.State.Players[1];Check(Driver.ActingSeat(e)==1&&Views.For(e,1).Reactions.Any(c=>c.Instance==counterId));e.React(counterId);
        Check(e.State.Pending==null&&e.State.Phase==stage);Check(victim.Hidden.SequenceEqual(hidden)&&victim.Declared.SequenceEqual(declared)&&victim.Hand.SequenceEqual(hand)&&victim.Tax==tax&&victim.Skip==skip,"L’attaque contrée a eu un effet.");
        Check(victim.Cash==100-e.Def(counterId).Cost&&victim.Discard.Contains(counterId));int refund=counter=="chien"?(attackDef.Cost+1)/2:0;Check(e.Active.Cash==100-attackDef.Cost+refund&&e.Active.Discard.Contains(attackId));Check(e.State.RandomState==random&&e.State.Thefts==0);Reject(()=>e.React(counterId));e.AssertConservation();
    });
}
