Console.WriteLine($"{passed} réussis ; {failed} échecs.");return failed==0?0:1;

static void Apply(Engine e,ActionOption a)
{
    switch(a.Kind){case "sell":e.Sell(a.Card);break;case "lock":e.InstallLock(a.Card);break;case "lockpick":e.UseLockpick(a.Card,a.Target!.Value);break;default:e.Play(new(a.Card,a.Target,a.Objects,a.Replay));break;}
}
